user_prompt_template:
CHAPTER WALKTHROUGH NARRATIVE (source of truth):
{chapter_narrative}

CHAPTER PLAN:
{current_chapter_json}

PROJECT CONTEXT:
Tutorial Request: {topic}
Document: {document_title}
Skill Level: {skill_level}
Stack: {stack}
Include Code: {include_code}
Output Style: {output_style}
Audience: {audience}
Tone: {tone}
Context: {context}

Generate structural chapter output for {domain_name} with scan/action/deep-read support.

QUALITY ENFORCEMENT NOTES (must be applied if present):
{structure_fix_instructions}

Return ONLY JSON with this exact top-level shape:

{{
  "chapter_number": {chapter_number},
  "domain_id": "domain ID from the chapter plan",
  "chapter_title": "Chapter title from the plan",
  "chapter_opener": {{
    "what_this_is_for": "One sentence: what this step builds and its role in the project",
    "when_it_matters": "Where this step sits in the build order and what must exist before starting it",
    "failure_looks_like": "Concrete symptom of this step going wrong — the error message, broken behavior, or missing output",
    "produces": ["Concrete artifact 1 — file, working feature, passing check", "Concrete artifact 2"],
    "do_first": ["First command or action", "Second command or action"]
  }},
  "minimum_viable_actions": ["3-6 fastest-path actions for a reader who wants to get this step working before reading deeply — real commands and file edits"],
  "quick_reference_rules": ["Actionable convention for this step — Rationale: ... Trigger: ... Risk: ..."],
  "decision_guide": [
    {{
      "decision": "Decision title — e.g. a version, tooling, or configuration fork",
      "if_condition": "Verifiable condition — what the reader observes or which setup they have",
      "then_action": "Exact action to take",
      "else_action": "Fallback action",
      "escalate_when": "Symptom that means stop and debug before continuing — exact error or behavior"
    }}
  ],
  "trigger_blocks": ["Specific symptom or event and the immediate response — e.g. 'If the build fails with <exact error>, run <command> and check <file>'"],
  "risk_blocks": ["Specific pitfall in this step and how to avoid or recover from it"],
  "output_summaries": ["Named artifact this step produces and why the next steps depend on it"],
  "worksheet_linkage": [
    {{
      "worksheet_title": "Exact checkpoint/exercise sheet title from the chapter plan",
      "use_when": "The exact moment in the step to use it",
      "unblocks": "What the reader can do once it passes"
    }}
  ],
  "cascade_triggers": ["When [specific verification in this step] passes, [specific action] in [named module] is unblocked"],
  "scenario_scene": "3-5 sentence worked-example vignette: a named developer hits a realistic snag in this step and resolves it with a concrete observable outcome",
  "success_metrics": ["3-5 verifiable completion checks — commands that succeed, outputs that appear, behavior observable in browser/terminal"],
  "detailed_explanation": "Deep how-it-works explanation only after structured layers are complete; paragraph length controlled and split into readable units"
}}
